-- ===========================================================================
-- Referentiel pays / villes — 66 pays, 8852 villes
--
-- Source : export du 06/08/2026 produit par l'equipe depuis la base
-- `alanyacenter` (schema `app`). Le corps de ce fichier — les deux blocs
-- INSERT — est repris SANS LA MOINDRE MODIFICATION : c'est lui le referentiel,
-- et les deux bases doivent designer le meme pays par le meme numero.
--
-- DEUX ADAPTATIONS, ET ELLES SONT INDISPENSABLES :
--
--   1. Le schema. La base en ligne n'a que `public` ; `app` n'existe pas.
--
--   2. La renumerotation des 25 pays deja presents. C'est le point critique.
--      Leurs numeros n'ont AUCUN rapport avec ceux du referentiel — pas un
--      seul ne coincide : l'identifiant 1 vaut « Cameroun » chez nous et
--      « Afrique du Sud » dans le referentiel, 20 vaut « Canada » contre
--      « Kenya », 3 « Cote d'Ivoire » contre « Angola ».
--
--      Sans cette renumerotation, `ON CONFLICT DO NOTHING` conserve nos lignes,
--      les pays 1 a 25 du referentiel ne sont JAMAIS inseres (l'Afrique du Sud,
--      le Kenya, Madagascar et la Libye manqueraient), les 41 suivants
--      s'ajoutent EN DOUBLE de ceux deja la (Mali en 11 et 26, France en 2 et
--      61...), et surtout les 1163 premieres villes — qui portent la
--      numerotation du referentiel — se rattachent au mauvais pays : Douala et
--      Yaounde en Afrique du Sud, Nairobi au Canada.
--
--      Les cinq cles etrangeres qui pointent sur `pays` sont toutes en
--      ON UPDATE CASCADE (`users`, `ville`, `company`, `adminroot`,
--      `prixabonnement`) : changer l'identifiant d'un pays met a jour tout
--      seul les 11 comptes qui le referencent. Verifie sur la base.
--
-- Le Royaume-Uni est le seul de nos pays absent du referentiel, qui ne couvre
-- que l'Afrique, l'Amerique du Nord et l'Europe occidentale. Il prend 67, le
-- premier numero libre — a signaler a l'equipe pour qu'elle s'aligne.
--
-- IDEMPOTENT, et il le faut : `scripts/apply-manual-sql.sh` rejoue tous les
-- `prisma/manual/*.sql` a chaque deploiement. La renumerotation ne s'execute
-- que si la table contient exactement 25 pays, c'est-a-dire l'etat d'avant
-- migration ; les INSERT sont en `ON CONFLICT DO NOTHING`.
-- ===========================================================================

BEGIN;

SET LOCAL search_path TO public;

-- --------------------------------------------------------------------------
-- 0. Aligner la numerotation des pays deja en base sur celle du referentiel.
-- --------------------------------------------------------------------------
DO $renum$
DECLARE
  nb_pays    integer;
  sans_cible integer;
BEGIN
  SELECT count(*) INTO nb_pays FROM pays;

  IF nb_pays <> 25 THEN
    RAISE NOTICE 'Renumerotation ignoree : % pays en base au lieu des 25 d''avant migration.', nb_pays;
    RETURN;
  END IF;

  -- Deux passes obligatoirement. Les numeros de depart et d'arrivee se
  -- chevauchent (le Cameroun va de 1 a 8, or 8 est deja pris par le Congo) :
  -- une affectation directe violerait la cle primaire des la premiere ligne.
  -- On degage donc d'abord toute la plage 1-100.
  UPDATE pays SET "idPays" = "idPays" + 1000;

  UPDATE pays SET "idPays" = 8   WHERE libelle = 'Cameroun';
  UPDATE pays SET "idPays" = 61  WHERE libelle = 'France';
  UPDATE pays SET "idPays" = 11  WHERE libelle = 'Côte d''Ivoire';
  UPDATE pays SET "idPays" = 46  WHERE libelle = 'Sénégal';
  UPDATE pays SET "idPays" = 38  WHERE libelle = 'RD Congo';
  UPDATE pays SET "idPays" = 14  WHERE libelle = 'Gabon';
  UPDATE pays SET "idPays" = 48  WHERE libelle = 'Tchad';
  UPDATE pays SET "idPays" = 37  WHERE libelle = 'Congo (Brazzaville)';
  UPDATE pays SET "idPays" = 7   WHERE libelle = 'Bénin';
  UPDATE pays SET "idPays" = 49  WHERE libelle = 'Togo';
  UPDATE pays SET "idPays" = 26  WHERE libelle = 'Mali';
  UPDATE pays SET "idPays" = 5   WHERE libelle = 'Burkina Faso';
  UPDATE pays SET "idPays" = 32  WHERE libelle = 'Niger';
  UPDATE pays SET "idPays" = 17  WHERE libelle = 'Guinée';
  UPDATE pays SET "idPays" = 27  WHERE libelle = 'Maroc';
  UPDATE pays SET "idPays" = 2   WHERE libelle = 'Algérie';
  UPDATE pays SET "idPays" = 50  WHERE libelle = 'Tunisie';
  UPDATE pays SET "idPays" = 33  WHERE libelle = 'Nigeria';
  UPDATE pays SET "idPays" = 16  WHERE libelle = 'Ghana';
  UPDATE pays SET "idPays" = 56  WHERE libelle = 'Canada';
  UPDATE pays SET "idPays" = 60  WHERE libelle = 'Belgique';
  UPDATE pays SET "idPays" = 66  WHERE libelle = 'Suisse';
  UPDATE pays SET "idPays" = 58  WHERE libelle = 'Allemagne';
  UPDATE pays SET "idPays" = 67  WHERE libelle = 'Royaume-Uni';
  UPDATE pays SET "idPays" = 57  WHERE libelle = 'États-Unis';

  -- Garde-fou : si un libelle n'a pas trouve sa correspondance, il est reste
  -- au-dessus de 1000. On interrompt plutot que de laisser la base a moitie
  -- renumerotee — la transaction entiere est annulee.
  SELECT count(*) INTO sans_cible FROM pays WHERE "idPays" > 1000;
  IF sans_cible > 0 THEN
    RAISE EXCEPTION 'Renumerotation incomplete : % pays sans correspondance dans le referentiel (%).',
      sans_cible,
      (SELECT string_agg(libelle, ', ') FROM pays WHERE "idPays" > 1000);
  END IF;

  RAISE NOTICE 'Renumerotation appliquee : 25 pays alignes sur le referentiel.';
END
$renum$;

