-- --------------------------------------------------------------------------
-- 4. Nom francais et anglais des 25 pays d'origine.
--
--    `ON CONFLICT DO NOTHING` laisse intactes les lignes deja presentes : leur
--    `libelleAnglais` serait donc reste vide, et « RD Congo » n'aurait jamais
--    pris le nom du referentiel. Cette mise a jour comble ce trou.
--
--    `prefix`, `timeZone` et `decalageHoraire` sont VOLONTAIREMENT laisses tels
--    quels : les notres portent un vrai decalage (60, 120, -300...) la ou le
--    referentiel a 0 partout. Les indicatifs et fuseaux, eux, concordent deja.
-- --------------------------------------------------------------------------
UPDATE pays p
   SET libelle          = r.libelle,
       "libelleAnglais" = r.anglais
  FROM (VALUES
  (8, 'Cameroun', 'Cameroon'),
  (61, 'France', 'France'),
  (11, 'Côte d''Ivoire', 'Côte d''Ivoire'),
  (46, 'Sénégal', 'Senegal'),
  (38, 'République démocratique du Congo', 'Democratic Republic of the Congo'),
  (14, 'Gabon', 'Gabon'),
  (48, 'Tchad', 'Chad'),
  (37, 'République du Congo', 'Congo'),
  (7, 'Bénin', 'Benin'),
  (49, 'Togo', 'Togo'),
  (26, 'Mali', 'Mali'),
  (5, 'Burkina Faso', 'Burkina Faso'),
  (32, 'Niger', 'Niger'),
  (17, 'Guinée', 'Guinea'),
  (27, 'Maroc', 'Morocco'),
  (2, 'Algérie', 'Algeria'),
  (50, 'Tunisie', 'Tunisia'),
  (33, 'Nigeria', 'Nigeria'),
  (16, 'Ghana', 'Ghana'),
  (56, 'Canada', 'Canada'),
  (60, 'Belgique', 'Belgium'),
  (66, 'Suisse', 'Switzerland'),
  (58, 'Allemagne', 'Germany'),
  (67, 'Royaume-Uni', 'United Kingdom'),
  (57, 'États-Unis', 'United States')
       ) AS r(id, libelle, anglais)
 WHERE p."idPays" = r.id;

-- --------------------------------------------------------------------------
-- 5. Recalage des sequences.
--
--    Sans ca, la premiere creation de pays ou de ville par l'application
--    repartirait de 1 et heurterait les lignes qu'on vient d'inserer.
--    `false` en troisieme argument : la valeur donnee sera la PROCHAINE rendue.
-- --------------------------------------------------------------------------
SELECT setval(
  pg_get_serial_sequence('pays', 'idPays'),
  coalesce((SELECT max("idPays") FROM pays), 0) + 1,
  false
);

SELECT setval(
  pg_get_serial_sequence('ville', 'idville'),
  coalesce((SELECT max(idville) FROM ville), 0) + 1,
  false
);

COMMIT;
